#!/bin/bash
# Tải 170 sticker PNG (Twemoji CC-BY 4.0 + Noto Emoji Apache-2.0).
# Chạy 1 lần sau khi clone:  bash assets/stickers/fetch_stickers.sh
# Mỗi file được kiểm tra SHA256. Chi tiết license: assets/SOURCES.md
#
# Twemoji graphics: Copyright Twitter, Inc — CC-BY 4.0
#   https://github.com/twitter/twemoji (code MIT, graphics CC-BY 4.0)
# Noto Emoji images: Copyright Google LLC — Apache-2.0
#   https://github.com/googlefonts/noto-emoji (fonts OFL 1.1, images Apache-2.0)
set -euo pipefail
cd "$(dirname "$0")"

PUB="../../apps/web/public/stickers"
mkdir -p "$PUB"

fetch() {
  local name="$1"; local url="$2"; local sha="$3"
  if [ -f "$name" ]; then echo "  có sẵn: $name";
  else
    echo "  tải: $name";
    curl -fsSL "$url" -o "$name";
  fi
  echo "$sha  $name" | sha256sum -c - > /dev/null \
    || { echo "LỖI checksum: $name"; exit 1; }
  cp -f "$name" "$PUB/$name"
}

